styles:
:root{--blue:#2563eb;--ink:#111827;--text:#374151;--muted:#64748b;--line:#e5e7eb;--bg:#f8fafc;--card:#fff;--pale:#eff6ff}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif;line-height:1.72}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.wrap{max-width:1080px;margin:auto;padding:0 20px}.nav{background:#fff;border-bottom:1px solid var(--line)}.navin{max-width:1080px;margin:auto;padding:14px 20px;min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.brand{font-size:25px;font-weight:800;color:var(--ink)}.brand span{color:var(--blue)}.links{display:flex;gap:18px;flex-wrap:wrap;font-size:14px;font-weight:700}.hero{background:linear-gradient(135deg,#eff6ff,#fff);padding:55px 0 45px;border-bottom:1px solid var(--line)}.eyebrow{font-size:12px;letter-spacing:1.2px;text-transform:uppercase;color:var(--blue);font-weight:800}.hero h1{font-size:clamp(32px,5vw,48px);line-height:1.12;letter-spacing:-1px;color:var(--ink);max-width:850px;margin:12px 0}.hero p{font-size:18px;max-width:800px}.meta{font-size:13px;color:var(--muted)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:26px;padding-top:30px;padding-bottom:55px;align-items:start}.content section,.side .card,.snapshot{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:25px;margin-bottom:18px}.content h2{font-size:26px;line-height:1.25;color:var(--ink);margin:0 0 14px}.content h3{font-size:19px;color:var(--ink);margin:22px 0 8px}.content p,.content li{font-size:15.5px}.content li{margin:7px 0}.snapshot{background:var(--ink);color:#fff}.snapshot strong{display:block;font-size:21px;margin:6px 0}.snapshot p{font-size:14px;color:#d1d5db}.toc h3{margin:0 0 10px;color:var(--ink)}.toc a{display:block;font-size:13px;padding:5px 0;border-bottom:1px solid #f1f5f9}.tablewrap{overflow-x:auto;margin:15px 0}.content table{width:100%;border-collapse:collapse;min-width:550px;font-size:14px}.content th,.content td{border:1px solid var(--line);padding:11px;text-align:left;vertical-align:top}.content th{background:#f1f5f9;color:var(--ink)}.note{font-size:13px;color:var(--muted);background:#f8fafc;border-left:3px solid #94a3b8;padding:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.mini{border:1px solid var(--line);border-radius:10px;padding:15px;background:#fff}.mini h3{margin-top:0}.callout{padding:16px;background:var(--pale);border-radius:10px;margin:16px 0}.resources{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.resources a{display:block;border:1px solid var(--line);padding:13px;border-radius:10px;font-weight:700}.resources span{display:block;font-size:13px;color:var(--muted);font-weight:400;margin-top:4px}details{padding:12px 0;border-bottom:1px solid var(--line)}summary{font-weight:700;color:var(--ink);cursor:pointer}.footer{background:#fff;border-top:1px solid var(--line);padding:25px 20px}.footin{max-width:1080px;margin:auto;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.footlinks{display:flex;gap:15px;flex-wrap:wrap;font-size:13px}
@media(max-width:800px){.layout{grid-template-columns:1fr}.side{order:-1}.toc{display:none}.grid,.resources{grid-template-columns:1fr}.hero{padding:38px 0}.content section{padding:19px}}
